mapper.select:
select ial.id, ial.resource_id, ial.account_name, ial.account_id, ic.name as channel, ial.status, sdi.item_text as statusName, ial.create_time, su.firstname as create_user from ins_account_lexicon ial left join voc_ms_be.sys_users su on su.id = ial.create_user left join voc_ms_td.ins_channel ic on ic.code = ial.channel left join (select sdi.item_text,sdi.item_value from voc_ms_be.ins_dict sd left join voc_ms_be.ins_dict_item sdi on sdi.dict_id = sd.id where sd.dict_code = 'enable_type' ) sdi on sdi.item_value = ial.status where 1=1
and ial.resource_id = #{insAccountLexicon.resourceId}
and ial.channel = #{insAccountLexicon.channel}
and (ial.account_name like concat('%',#{insAccountLexicon.keyword},'%') or ial.account_id like concat('%',#{insAccountLexicon.keyword},'%'))
